package pluginutil

import "testing"

// Test data: the real mangafire VRF tables/keys (rotates with keiyoushi
// updates — replace when the site rotation happens).
var (
	vrfK1 = "0Ec58JOY3uBzJK9m3zqIOpdlF7UFiax9DmA="
	vrfT1 = ""
	vrfK2 = "AAdjb1iPY8CiDmq9H34tKTBF8a3oDQ=="
	vrfT2 = ""
	vrfK3 = "DELOJgPsVaCcblDtTGMdHzM="
	vrfT3 = ""
)

func vrfTestStages(t *testing.T) []VRFStage {
	t.Helper()
	st, err := VRFStagesB64([]VRFStageB64{
		{IV: 0x5A, Key: vrfK1, Tbl: vrfT1},
		{IV: 0x35, Key: vrfK2, Tbl: vrfT2},
		{IV: 0xBA, Key: vrfK3, Tbl: vrfT3},
	})
	if err != nil {
		t.Fatalf("decode stages: %v", err)
	}
	return st
}

// Golden vectors generated by the live JS plugin implementation
// (examples/plugins/js/mangafire/main.js) — byte-for-byte parity required.
func TestVRFSignGolden(t *testing.T) {
	st := vrfTestStages(t)
	cases := []struct {
		name    string
		apiPath string
		params  map[string]string
		want    string
	}{
		{"empty", "/titles", map[string]string{}, "8sK3xtqdFQ"},
		{"one", "/manga", map[string]string{"limit": "50"}, "8qEkqsbjQMrPN82PZEAP"},
		{"sorted", "/titles", map[string]string{"keyword": "naruto", "limit": "50", "page": "1"}, "8sK3xtqdFZfetBhus6bRAjHyEL3W3G_rnxgOXpPB0_i8tncqWLs"},
		{"apiStrip", "/api/titles", map[string]string{"page": "2"}, "8sK3xtqdFZfnfxImVdE"},
		{"utf8", "/search", map[string]string{"q": "はじめの一歩"}, "8rmP5f_9tOdgg-j3a5w_WQte2iUPEj6pvQYSPw"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got := VRFSign(tc.apiPath, tc.params, st)
			if got != tc.want {
				t.Errorf("VRFSign(%q, %v) = %q, want %q", tc.apiPath, tc.params, got, tc.want)
			}
		})
	}
}

func TestVRFStagesB64Error(t *testing.T) {
	if _, err := VRFStagesB64([]VRFStageB64{{Key: "!!!", Tbl: "!!!"}}); err == nil {
		t.Fatal("expected error for invalid base64")
	}
}
